#pragma once
#include "Creatures/Core/Creature.h"
#include "Render/Camera/Camera.h"
#include "Render/Camera/WorldCameraSweep.h"
#include "World/Core/World.h"
#include "World/Core/BlockWorld.h"
#include "App/Platform/WindowManager.h"
#include "World/Mesh/WorldMeshService.h"
#include <fstream>
#include <filesystem>
#include <nlohmann/json.hpp>
#include <unordered_set>

namespace cutum {
// Opt-in native acceptance route. Only disposable HumanMotionQa_* worlds can
// receive the fixture. All poses are generated by normal keys and the motor.
template<class Window> inline void TickHumanMotionQa(UWorld &world,UCamera &camera,Window &window,double time) {
 const char *path=std::getenv("CUBA_HUMAN_MOTION_QA");if(!path || !*path)return;
 if(world.GetWorldFolderPath().find("HumanMotionQa_")==std::string::npos)return;
 static bool initialized=false;static glm::ivec3 origin;static int previous=-1;
 static glm::vec3 previousCamera(0.f);static bool cameraSeeded=false;
 static std::ofstream out;static double start=0;
 if(!initialized) {
  if(time<2.0)return;
  world.SetTimeOfDayNormalized(.35f);world.SetTimeFrozen(true);
  origin=WorldPosToBlock(camera.GetPosition());origin.y-=3;
  auto &blocks=world.GetBlockWorld();
  BlockId solid=world.GetBlockRegistry().GetIdByTypeName("stone");
  if(solid==BLOCK_AIR)return;
  std::vector<glm::ivec3> changed;
  for(int x=-12;x<=16;++x)for(int z=-12;z<=16;++z)for(int y=0;y<=14;++y) {
   const auto cell=origin+glm::ivec3(x,y,z);blocks.SetBlock(cell,y==0?solid:BLOCK_AIR);changed.push_back(cell);
  }
  // Filled above the floor: no collider or buoyancy modifications.
  const BlockId water=world.GetBlockRegistry().GetIdByTypeName("water");
  for(int x=5;x<=15;++x)for(int z=-5;z<=12;++z)for(int y=1;y<=7;++y)
   blocks.SetBlock(origin+glm::ivec3(x,y,z),water);
  for(int y=1;y<=8;++y) {
    for(int z=-6;z<=13;++z){blocks.SetBlock(origin+glm::ivec3(4,y,z),solid);blocks.SetBlock(origin+glm::ivec3(16,y,z),solid);}
    for(int x=4;x<=16;++x){blocks.SetBlock(origin+glm::ivec3(x,y,-6),solid);blocks.SetBlock(origin+glm::ivec3(x,y,13),solid);}
  }
  for(int x=-5;x<=4;++x)for(int y=1;y<=7;++y)blocks.SetBlock(origin+glm::ivec3(x,y,-3),solid);
  for(int z=-3;z<=5;++z)for(int y=1;y<=7;++y)blocks.SetBlock(origin+glm::ivec3(-5,y,z),solid);
  for(int y=1;y<=5;++y)blocks.SetBlock(origin+glm::ivec3(-2,y,-2),solid); // Solid voxel pillar: an external camera corner.
  std::unordered_set<glm::ivec3,IVec3Hash> dirty;
  world.GetMeshService().MarkBlocksChunkDirtyBatchFromEdit(blocks,&world.GetBlockRegistry(),changed,dirty,true,false);
  std::filesystem::create_directories(std::filesystem::path(path).parent_path());out.open(path);
  initialized=true;start=time;
 }
 const double t=time-start;const int stage=std::min(16,static_cast<int>(t/2.));
 const bool stageChanged=stage!=previous;
 static const char *names[]={"idle","walk","run","crouch_walk","jump","fall","hover","fly_up","fly_down","fly_forward","surface_idle","surface_swim","submerged_idle","swim_up","swim_forward","camera_back","camera_front"};
 if(stage!=previous) {
  window.ClearAutopilotKeys();camera.ResetAllKeyStatus();
  glm::vec3 eye=glm::vec3(origin)+glm::vec3(0,.5f+1.62f,0);
  if(stage==5)eye.y+=6;
  if(stage>=6 && stage<=9)eye.y+=12;
  if(stage>=10 && stage<=14){eye.x+=9;eye.z=origin.z;eye.y=origin.y+(stage<12?7.6f:5.f);}
  camera.ResetVerticalPhysics();
  camera.SetFreeMove(stage>=6 && stage<=9);
  camera.SetPosition(eye);camera.SetOrientation(90.f,-8.f);
  const auto desired=stage==16?CameraPerspective::ThirdPersonFront:CameraPerspective::ThirdPersonBack;
  for(int i=0;i<3 && camera.GetPerspective()!=desired;++i)camera.CycleFpsPerspective();
  previous=stage;
 }
 window.SetAutopilotKey(KeyCode::Key_W,stage==1 || stage==2 || stage==3 || stage==4 || stage==9 || stage==11 || stage==14);
 window.SetAutopilotKey(KeyCode::Key_Ctrl,stage==2);
 window.SetAutopilotKey(KeyCode::Key_Shift,stage==3 || stage==8);
 window.SetAutopilotKey(KeyCode::Key_Space,stage==7 || stage==13 || (stage==4 && std::fmod(t,2.)>.5 && std::fmod(t,2.)<.75));
 if(stage>=15)camera.SetOrientation(static_cast<float>(t*170.),static_cast<float>(60.*std::sin(t*2.)));
 if(stageChanged){cameraSeeded=false;return;}
 // Read the last presented camera; resolving here would insert an extra
 // unpresented step and invalidate the inter-frame straight-path check.
 const auto p=camera.GetRenderPosition(),eye=camera.GetPosition();
 nlohmann::json row={{"time",t},{"scenario",names[stage]},{"eye",{eye.x,eye.y,eye.z}},{"camera",{p.x,p.y,p.z}},{"radius",camera.GetCameraCollisionRadius()},{"camera_clear",SweepCameraVolume(world,p,p,camera.GetCameraCollisionRadius())>=1.f}};
 row["path_clear"]=!cameraSeeded || stageChanged || SweepCameraVolume(world,previousCamera,p,camera.GetCameraCollisionRadius())>=1.f;
 previousCamera=p;cameraSeeded=true;
 if(const auto *actor=world.GetControlledCreature()) {
  const auto &f=actor->GetLocomotionFacts();row["velocity"]={f.actualVelocity.x,f.actualVelocity.y,f.actualVelocity.z};
  row["on_ground"]=f.onGround;row["swimming"]=f.swimming;row["head_submerged"]=f.headSubmerged;row["stance"]=f.stanceBlend;
  row["mode"]=static_cast<int>(actor->HumanMotion.mode);row["landing_events"]=actor->HumanMotion.landingEvents;
 }
 out<<row.dump()<<'\n';out.flush();
}
}
